<?php
namespace App\Http\Controllers; use App\Models\{Application,Company,Job,Payment,User,Worker}; use Illuminate\Http\Request; use Illuminate\View\View;
class DashboardController extends Controller { public function __invoke(Request $request):View{$user=$request->user();if($user->hasRole('admin'))$stats=['Pengguna'=>User::count(),'Perusahaan'=>Company::count(),'Worker'=>Worker::count(),'Lowongan'=>Job::count()];elseif($user->hasRole('company')){$id=$user->company->id;$stats=['Lowongan'=>Job::where('company_id',$id)->count(),'Lowongan Aktif'=>Job::where('company_id',$id)->where('status','published')->count(),'Pelamar'=>Application::whereHas('job',fn($q)=>$q->where('company_id',$id))->count(),'Pembayaran'=>Payment::whereHas('application.job',fn($q)=>$q->where('company_id',$id))->sum('total')];}else{$id=$user->worker->id;$stats=['Lamaran'=>Application::where('worker_id',$id)->count(),'Diterima'=>Application::where('worker_id',$id)->where('status','accepted')->count(),'Selesai'=>Application::where('worker_id',$id)->where('status','completed')->count(),'Saldo'=>$user->wallet->balance];}return view('dashboard',compact('stats','user'));} }
